import {useState, useCallback} from 'react'

export interface DatePickerPartialProps {
  initialValue?: number | null
  name: string
  hiddenInputId?: string
  onMillisChange?: (ms: number | null) => void
  className?: string
  placeholder?: string
  minDate?: number
  maxDate?: number
}

export default function DatePickerField({
  initialValue,
  name,
  hiddenInputId = 'discussion_due_date',
  onMillisChange,
  className = '',
  placeholder = 'Select a date...',
  minDate,
  maxDate,
}: DatePickerPartialProps) {
  const [selected, setSelected] = useState<Date | null>(() =>
    typeof initialValue === 'number' ? new Date(initialValue) : null,
  )

  const formatDateForInput = (date: Date | null): string => {
    if (!date) return ''
    const year = date.getFullYear()
    const month = String(date.getMonth() + 1).padStart(2, '0')
    const day = String(date.getDate()).padStart(2, '0')
    return `${year}-${month}-${day}`
  }

  const timestampToInputFormat = (timestamp: number | undefined): string => {
    if (!timestamp) return ''
    return formatDateForInput(new Date(timestamp))
  }

  const handleChange = useCallback(
    (event: React.ChangeEvent<HTMLInputElement>) => {
      const value = event.target.value
      const date = value ? new Date(`${value}T00:00:00`) : null

      setSelected(date)

      const ms = date ? date.getTime() : null
      onMillisChange?.(ms)
    },
    [onMillisChange],
  )

  return (
    <div className={`date-picker-native-wrapper ${className}`}>
      <input type="hidden" className="js-discussion-timestamp" name={name} defaultValue="" />

      <div className="date-input-container">
        <svg
          className="calendar-icon"
          width="20"
          height="20"
          viewBox="0 0 24 24"
          fill="currentColor"
          aria-hidden="true"
        >
          <path d="M19 3h-1V1h-2v2H8V1H6v2H5c-1.11 0-1.99.9-1.99 2L3 19c0 1.1.89 2 2 2h14c1.1 0 2-.9 2-2V5c0-1.1-.9-2-2-2zm0 16H5V8h14v11zM7 10h5v5H7z" />
        </svg>

        <input
          type="date"
          className={`date-input-native js-discussion-due-date ${!selected ? 'date-input-empty' : ''}`}
          id={hiddenInputId}
          value={formatDateForInput(selected)}
          onChange={handleChange}
          min={timestampToInputFormat(minDate)}
          max={timestampToInputFormat(maxDate)}
          aria-label={placeholder}
          data-placeholder={placeholder}
        />
      </div>
    </div>
  )
}
